pub struct TokensPage;

impl Page for TokensPage {
    fn name(&self) -> &'static str {
        "Tokens"
    }

    fn ui(&mut self, ui: &mut egui::Ui) {
        let colors = Theme::get(ui.ctx()).color;
        ui.heading("Alias colours");
        ui.label("Every field of the installed theme's AliasColors.");
        ui.add_space(8.0);
        egui::Grid::new("alias_colors")
            .num_columns(2)
            .spacing([12.0, 6.0])
            .striped(true)
            .show(ui, |ui| {
                for (name, read) in FIELDS {
                    let rgba = read(&colors);
                    let (rect, _) = ui.allocate_exact_size(egui::vec2(28.0, 18.0), egui::Sense::hover());
                    ui.painter().rect_filled(rect, 2.0, color32(rgba));
                    ui.painter().rect_stroke(
                        rect,
                        2.0,
                        egui::Stroke::new(1.0, Color32::from_gray(128)),
                        egui::StrokeKind::Inside,
                    );
                    ui.label(*name);
                    ui.end_row();
                }
            });
    }
}

fn color32(rgba: Rgba) -> Color32 {
    Color32::from_rgba_unmultiplied(rgba.r, rgba.g, rgba.b, rgba.a)
}
